New York.q_heights:
SELECT ?b ?coord ?hm ?rank ?part ?crit WHERE {
  SERVICE wikibase:around {
    ?b wdt:P625 ?coord .
    bd:serviceParam wikibase:center "Point(-74.006 40.713)"^^geo:wktLiteral .
    bd:serviceParam wikibase:radius "30.0" .
  }
  ?b p:P2048 ?st .
  ?st psn:P2048/wikibase:quantityAmount ?hm .
  ?st wikibase:rank ?rank .
  FILTER(?hm >= 50.0)
  OPTIONAL { ?st pq:P518 ?part }
  OPTIONAL { ?st pq:P1013 ?crit }
}

